'=>'Enviado','delivered'=>'Entregue'] as $key=>$label)<option @selected($order->shipping_status==$key) value="{{ $key }}">{{ $label }}</option>@endforeach</select></label><label>Código de rastreio<input name="tracking_code" value="{{ $order->shipment?->tracking_code }}"></label><label>Link de rastreamento<input name="tracking_url" type="url" value="{{ $order->shipment?->tracking_url }}"></label><button class="btn btn-dark block">Salvar atualização</button></form>@if($order->financial_status==='paid'&&config('shop.payment_mode')==='demo'&&in_array(auth()->user()->role,['superadmin','admin']))<form method="post" action="{{ route('admin.orders.refund',$order) }}" onsubmit="return confirm('Simular reembolso financeiro? Nenhum valor será transferido.')">@csrf<label class="checkline"><input type="checkbox" name="restock" value="1"> Repor estoque (somente se houve devolução física)</label><button class="btn btn-outline small">Registrar reembolso demonstrativo</button></form>@endif @if($order->financial_status==='pending')<form method="post" action="{{ route('admin.orders.update',$order) }}" onsubmit="return confirm('Cancelar este pedido e liberar reservas?')">@csrf @method('PATCH')<input type="hidden" name="cancel_pending" value="1"><button class="remove-link">Cancelar pedido pendente</button></form>@endif</section></div>@endsection
